-- ============================================================
-- 048_stays.sql — villa-desk: stays, Stay Reference, form token
--
-- A "stay" is one pre-arrival registration (PDR sections 4 and 11).
--
--   * stay_ref   MS-YYYY-NNN, unique per account, sequence resets each
--                calendar year. Generated by next_stay_ref(), which
--                locks a per-year counter row, so two simultaneous
--                saves can never share a number.
--   * form_token 14-character random code for the public /stay/<token>
--                guest form (unique).
--   * guest_phone stored as digits with country code (normalised by a
--                trigger, matched on that form only).
--   * status     draft -> registered happens automatically when a valid
--                mobile number is present, and back to draft if it is
--                removed. cancelled / sample are never automation-ready.
--   * automation_ready  GENERATED column: the allow-list reads it. The
--                time-based "closed 7 days after checkout" rule lives in
--                isAutomationAllowed(), because a generated column must
--                be immutable.
--
-- Nothing here ever deletes a stay: children reference stays with the
-- default NO ACTION, and there is no DELETE policy. Cancelling is a
-- status, not a delete.
--
-- Idempotent — safe to run multiple times.
-- ============================================================

-- ------------------------------------------------------------
-- Per-year counter for Stay References. RLS on, no policies: only
-- the SECURITY DEFINER function below (and service_role) touches it.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stay_ref_counters (
  account_id UUID    NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  year       INTEGER NOT NULL,
  last_value INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (account_id, year)
);
ALTER TABLE stay_ref_counters ENABLE ROW LEVEL SECURITY;

-- INSERT .. ON CONFLICT DO UPDATE takes a row lock, so concurrent
-- callers serialise on the (account, year) row and each gets a
-- distinct number.
CREATE OR REPLACE FUNCTION public.next_stay_ref(p_account_id UUID, p_year INTEGER)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_n INTEGER;
BEGIN
  INSERT INTO stay_ref_counters AS c (account_id, year, last_value)
  VALUES (p_account_id, p_year, 1)
  ON CONFLICT (account_id, year)
  DO UPDATE SET last_value = c.last_value + 1
  RETURNING c.last_value INTO v_n;

  RETURN 'MS-' || p_year::text || '-' || lpad(v_n::text, 3, '0');
END;
$$;

REVOKE ALL ON FUNCTION public.next_stay_ref(UUID, INTEGER) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.next_stay_ref(UUID, INTEGER) TO service_role;

-- ------------------------------------------------------------
-- 14-character form token. gen_random_uuid() is a CSPRNG; 14 hex
-- characters is 56 bits, on top of the 20-requests-per-10-minutes
-- per-IP limit on the public route.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.generate_stay_token()
RETURNS TEXT
LANGUAGE sql
VOLATILE
AS $$
  SELECT substr(replace(gen_random_uuid()::text, '-', ''), 1, 14);
$$;

-- ------------------------------------------------------------
-- stays
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stays (
  id            UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  account_id    UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  property_id   UUID NOT NULL REFERENCES properties(id) ON DELETE RESTRICT,
  -- Link to the upstream contacts row so a returning guest appears in
  -- the inbox and the conversation is shared.
  contact_id    UUID REFERENCES contacts(id) ON DELETE SET NULL,

  stay_ref      TEXT NOT NULL,
  form_token    TEXT NOT NULL DEFAULT public.generate_stay_token(),

  guest_name    TEXT NOT NULL,
  guest_phone   TEXT,
  guest_email   TEXT,

  source        TEXT NOT NULL DEFAULT 'direct'
                  CHECK (source IN ('airbnb', 'booking_com', 'makemytrip', 'goibibo', 'direct', 'other')),
  -- The platform's own booking ID exactly as typed (trimmed, no format
  -- check). NOT used for automation gating.
  external_booking_ref TEXT CHECK (char_length(external_booking_ref) <= 100),

  status        TEXT NOT NULL DEFAULT 'draft'
                  CHECK (status IN ('draft', 'registered', 'checked_in', 'checked_out', 'cancelled', 'sample')),
  form_status   TEXT NOT NULL DEFAULT 'pending'
                  CHECK (form_status IN ('pending', 'submitted')),
  form_submitted_at TIMESTAMPTZ,

  checkin_at    TIMESTAMPTZ NOT NULL,
  checkout_at   TIMESTAMPTZ NOT NULL,
  guests_count  INTEGER NOT NULL DEFAULT 1 CHECK (guests_count >= 1),

  -- Filled in from the public guest form (PDR 6.2, Arrival block).
  expected_arrival_time TIME,
  vehicle_number        TEXT,
  special_request       TEXT,
  purpose_of_visit      TEXT,

  notes         TEXT,
  automation_paused BOOLEAN NOT NULL DEFAULT FALSE,
  guest_arrived_at  TIMESTAMPTZ,   -- set by the READY / arrival logic
  closed_at     TIMESTAMPTZ,       -- hides old stays from default views

  created_by    UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT stays_checkout_after_checkin CHECK (checkout_at > checkin_at),
  CONSTRAINT stays_phone_digits CHECK (guest_phone IS NULL OR guest_phone ~ '^[0-9]{8,15}$'),

  -- The allow-list reads this column (PDR 4.1 / 4.2).
  automation_ready BOOLEAN GENERATED ALWAYS AS (
    stay_ref IS NOT NULL
    AND guest_phone IS NOT NULL
    AND guest_phone ~ '^[0-9]{8,15}$'
    AND status IN ('registered', 'checked_in', 'checked_out')
    AND NOT automation_paused
  ) STORED
);

-- Unique per account, and the token must be globally unique so the
-- public route can look it up without knowing the account.
CREATE UNIQUE INDEX IF NOT EXISTS uq_stays_account_ref   ON stays(account_id, stay_ref);
CREATE UNIQUE INDEX IF NOT EXISTS uq_stays_form_token    ON stays(form_token);

-- Two live stays on one number are not allowed (PDR 11).
CREATE UNIQUE INDEX IF NOT EXISTS uq_stays_live_phone
  ON stays(account_id, guest_phone)
  WHERE guest_phone IS NOT NULL AND status IN ('registered', 'checked_in');

CREATE INDEX IF NOT EXISTS idx_stays_account_checkin  ON stays(account_id, checkin_at);
CREATE INDEX IF NOT EXISTS idx_stays_account_checkout ON stays(account_id, checkout_at);
CREATE INDEX IF NOT EXISTS idx_stays_phone            ON stays(account_id, guest_phone);
CREATE INDEX IF NOT EXISTS idx_stays_external_ref
  ON stays(account_id, source, lower(external_booking_ref))
  WHERE external_booking_ref IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_stays_property         ON stays(property_id);
CREATE INDEX IF NOT EXISTS idx_stays_contact          ON stays(contact_id);

-- ------------------------------------------------------------
-- BEFORE INSERT/UPDATE: normalise, assign the reference, and keep
-- draft <-> registered in step with the mobile number.
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.stays_before_write()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  -- Phone: digits only (matches normalizePhone() in the app).
  IF NEW.guest_phone IS NOT NULL THEN
    NEW.guest_phone := NULLIF(regexp_replace(NEW.guest_phone, '\D', '', 'g'), '');
  END IF;

  -- Booking reference: trimmed, empty becomes NULL.
  IF NEW.external_booking_ref IS NOT NULL THEN
    NEW.external_booking_ref := NULLIF(btrim(NEW.external_booking_ref), '');
  END IF;

  -- Stay Reference: assigned once, never changed afterwards.
  IF TG_OP = 'INSERT' THEN
    IF NEW.stay_ref IS NULL OR NEW.stay_ref = '' THEN
      NEW.stay_ref := public.next_stay_ref(
        NEW.account_id,
        EXTRACT(YEAR FROM (NOW() AT TIME ZONE 'Asia/Kolkata'))::INTEGER
      );
    END IF;
  ELSIF NEW.stay_ref IS DISTINCT FROM OLD.stay_ref THEN
    RAISE EXCEPTION 'stay_ref is immutable (%).', OLD.stay_ref;
  END IF;

  -- A valid mobile number turns a draft into a registration at once;
  -- removing it puts a registration back to draft.
  IF NEW.status = 'draft'
     AND NEW.guest_phone IS NOT NULL
     AND NEW.guest_phone ~ '^[0-9]{8,15}$' THEN
    NEW.status := 'registered';
  ELSIF NEW.status = 'registered' AND NEW.guest_phone IS NULL THEN
    NEW.status := 'draft';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.updated_at := NOW();
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS stays_before_write ON stays;
CREATE TRIGGER stays_before_write
  BEFORE INSERT OR UPDATE ON stays
  FOR EACH ROW EXECUTE FUNCTION public.stays_before_write();

-- ------------------------------------------------------------
-- RLS. Reads: any member (caretaker and viewer included). Writes:
-- admin and above. No DELETE policy: nobody deletes a stay through
-- the API, and child foreign keys block it in SQL too.
-- ------------------------------------------------------------
ALTER TABLE stays ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS stays_select ON stays;
CREATE POLICY stays_select ON stays
  FOR SELECT USING (is_account_member(account_id));

DROP POLICY IF EXISTS stays_insert ON stays;
CREATE POLICY stays_insert ON stays
  FOR INSERT WITH CHECK (is_account_member(account_id, 'admin'));

DROP POLICY IF EXISTS stays_update ON stays;
CREATE POLICY stays_update ON stays
  FOR UPDATE USING (is_account_member(account_id, 'admin'));
